head.script:
scwin.screenId = "jldfil35708";

///////// 1. 변수 및 선언 영역 /////////

scwin.data = null;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신
        await scwin.init_pageBody(); // 2) 수수료 계산 결과 렌더 + 인쇄 호출
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35708.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 페이지 본문 초기화 — fn_init 를 호출해 호스트 화면에서 받은 증권상품 수수료 계산 데이터를 렌더하고, 실패 시 공통 오류 처리한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.init_pageBody();
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fn_init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: 'jldfil35708.onpageload' });
    }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fn_init
 * @description 호스트 화면(파라미터 dataArr_trust 또는 오프너 scwin.dataArr_trust)에서 증권상품(ETF/ETN/ELW/상장형 수익증권) 수수료 계산 데이터를 받아 수수료구분·원본액 라벨을 판정해 표기하고, 종목별 종목코드/원본액/수수료와 총액·부과수수료를 입력 필드에 렌더한 뒤 인쇄 팝업($c.win.popupPrint)을 호출한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_init();
 */
scwin.fn_init = async function () {
    const param = $c.data.getParameter();
    const openerScwin = ((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {};
    const dataSrc = (param && typeof param === 'object' && Object.keys(param).length) ? param : openerScwin;
    scwin.data = dataSrc.dataArr_trust;
    if (!Array.isArray(scwin.data)) {
        console.warn('[sdd] 인쇄 데이터 부재(호스트 진입 필요) — jldfil35708');
        return;
    }
    const gubun = scwin.data[11].calc_gubun;
    if (gubun === "1") {
        $c.util.getComponent("ipt_calcGubun").setValue("ETF");
        $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
    } else {
        if (gubun === "2") {
            $c.util.getComponent("ipt_calcGubun").setValue("ETN");
            $c.util.getComponent('txt_tdNm4').setLabel("* 발행원본액");
        } else {
            if (gubun === "3") {
                $c.util.getComponent("ipt_calcGubun").setValue("ELW");
                $c.util.getComponent('txt_tdNm4').setLabel("* 발행총액");
            } else {
                if (gubun === "4") {
                    $c.util.getComponent("ipt_calcGubun").setValue("상장형 수익증권");
                    $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
                }
            }
        }
    }
    $c.util.getComponent("ipt_issueCode1").setValue(scwin.data[0].issueCode);
    $c.util.getComponent("ipt_issueCode2").setValue(scwin.data[1].issueCode);
    $c.util.getComponent("ipt_issueCode3").setValue(scwin.data[2].issueCode);
    $c.util.getComponent("ipt_issueCode4").setValue(scwin.data[3].issueCode);
    $c.util.getComponent("ipt_issueCode5").setValue(scwin.data[4].issueCode);
    $c.util.getComponent("ipt_issueCode6").setValue(scwin.data[5].issueCode);
    $c.util.getComponent("ipt_issueCode7").setValue(scwin.data[6].issueCode);
    $c.util.getComponent("ipt_issueCode8").setValue(scwin.data[7].issueCode);
    $c.util.getComponent("ipt_issueCode9").setValue(scwin.data[8].issueCode);
    $c.util.getComponent("ipt_issueCode10").setValue(scwin.data[9].issueCode);
    $c.util.getComponent("ipt_commission1").setValue(scwin.data[0].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_1'));
    $c.util.getComponent("ipt_commission2").setValue(scwin.data[1].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_2'));
    $c.util.getComponent("ipt_commission3").setValue(scwin.data[2].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_3'));
    $c.util.getComponent("ipt_commission4").setValue(scwin.data[3].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_4'));
    $c.util.getComponent("ipt_commission5").setValue(scwin.data[4].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_5'));
    $c.util.getComponent("ipt_commission6").setValue(scwin.data[5].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_6'));
    $c.util.getComponent("ipt_commission7").setValue(scwin.data[6].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_7'));
    $c.util.getComponent("ipt_commission8").setValue(scwin.data[7].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_8'));
    $c.util.getComponent("ipt_commission9").setValue(scwin.data[8].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_9'));
    $c.util.getComponent("ipt_commission10").setValue(scwin.data[9].trust_comm);
    await scwin.numFormat($c.util.getComponent('commission_10'));
    $c.util.getComponent("ipt_trustCount1").setValue(scwin.data[0].trust_count);
    $c.util.getComponent("ipt_trustCount2").setValue(scwin.data[1].trust_count);
    $c.util.getComponent("ipt_trustCount3").setValue(scwin.data[2].trust_count);
    $c.util.getComponent("ipt_trustCount4").setValue(scwin.data[3].trust_count);
    $c.util.getComponent("ipt_trustCount5").setValue(scwin.data[4].trust_count);
    $c.util.getComponent("ipt_trustCount6").setValue(scwin.data[5].trust_count);
    $c.util.getComponent("ipt_trustCount7").setValue(scwin.data[6].trust_count);
    $c.util.getComponent("ipt_trustCount8").setValue(scwin.data[7].trust_count);
    $c.util.getComponent("ipt_trustCount9").setValue(scwin.data[8].trust_count);
    $c.util.getComponent("ipt_trustCount10").setValue(scwin.data[9].trust_count);
    $c.util.getComponent("ipt_totListAmtTrust").setValue(scwin.data[10].tot_list_amt_trust);
    $c.util.getComponent("ipt_listCommSumTrust").setValue(scwin.data[10].list_comm_sum_trust);
    $c.win.popupPrint();
};


/**
 * @method
 * @name unformat
 * @description 입력 요소 값에서 숫자(0~9)와 부호(-)만 남기고 콤마 등 나머지 문자를 제거해 되돌려 넣는다.
 * @param {Object} obj value 속성을 가진 입력 요소
 * @returns {Boolean} 항상 true
 * @hidden N
 * @example scwin.unformat(obj);
 */
scwin.unformat = function (obj) {
    let temp = "";
    const n = String(obj.value);
    const len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
            temp = temp + ch;
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
};


/**
 * @method
 * @name numFormat
 * @description 입력 요소 값을 숫자 검증(isMinusNum) 후 3자리 콤마 형식으로 변환한다. 숫자가 아니면 값을 비우고 경고 알림 후 포커스를 되돌린다.
 * @param {Object} obj value 속성을 가진 입력 요소
 * @returns {void}
 * @hidden N
 * @example await scwin.numFormat(obj);
 */
scwin.numFormat = async function (obj) {
    if (obj.value !== "" && !scwin.isMinusNum(obj.value)) {
        obj.value = "";
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    scwin.unformat(obj);
    if (obj.value === "") {
        return;
    }
    if (isNaN(obj.value)) {
        obj.value = "";
        return;
    }
    let str = Number(obj.value) + "";
    let sMinusChar = "";
    if (Number(obj.value) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    const leng = str.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.value = Number(obj.value);
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + str.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.value = sMinusChar + result.substring(1);
        } else {
            obj.value = sMinusChar + str.substr(0, pos) + result;
        }
    }
    return;
};


/**
 * @method
 * @name isMinusNum
 * @description 문자열이 부호(-) 허용 숫자인지 판별한다 — 첫 글자는 0~9 또는 '-', 이후 글자는 모두 0~9 여야 true.
 * @param {String} name 검사할 문자열
 * @returns {Boolean} 부호 허용 숫자 여부
 * @hidden N
 * @example const ok = scwin.isMinusNum("-1234");
 */
scwin.isMinusNum = function (name) {
    let ch = "\0";
    let flag = true;
    ch = name.charAt(0);
    flag = ((ch >= '0' && ch <= '9') || ch === '-') ? true : false;
    for (let i = 1; (i < name.length) && (flag); i = i + 1) {
        ch = name.charAt(i);
        if ((ch >= '0') && (ch <= '9')) {

        } else {
            flag = false;
        }
    }
    return flag;
};
